window.AUTH=window.AUTH||{};window.AUTH["05-996"]={"d":"05-996","id":"2006/05-996","n":"Marrama v. Citizens Bank of Massachusetts","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondents","date":"","url":"https://www.justice.gov/osg/media/212866/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/marrama-v-citizens-bank-amicus-merits","n":76}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep549/usrep549365/usrep549365.pdf","tr":true,"items":[{"t":"case","label":"Alt v. United States (In re Alt)","cite":"305 F.3d 413","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/305/413/","op":1,"by":{"0":"17"}},{"t":"case","label":"Boroff v. Tully (In re Tully)","cite":"818 F.2d 106","y":1987,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/818/106/","by":{"0":"26"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"ar":2,"sum":"The District Court properly invoked its inherent power in assessing as a sanction for Chambers' bad-faith conduct the attorney's fees and related expenses paid by NASCO.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Citizens Bank & Trust Co. v. Case (In re Case)","cite":"937 F.2d 1014","y":1991,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/937/1014/","by":{"0":"12"}},{"t":"case","label":"Eisen v. Curry (In re Eisen)","cite":"14 F.3d 469","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/14/469/","by":{"0":"17"}},{"t":"case","label":"Independent Fed’n of Flight Attendants v. Zipes","cite":"491 U.S. 754","y":1989,"id":"1988/88-608","sc":1,"sum":"District courts may award Title VII attorney's fees against those who are not charged with Title VII violations but intervene to protect their own rights only where the intervention is frivolous, unreasonable, or without foundation. Assessing fees against blameless intervenors is not essential to § 706(k)'s central purpose of providing victims of wrongful discrimination an incentive to file suit. The prospect of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Link v. Wabash R.R.","cite":"370 U.S. 626","y":1962,"id":"1961/422","sc":1,"ar":1,"sum":"The Court held that a court has the right to clear its calendar of cases that have been dormant because of inaction on the part of the plaintiff without any motion from the defense. This right has long been understood as one of the inherent powers of the court and no law explicitly restricts it.","sumSrc":"Oyez","by":{"0":"7, 8, 10, 17"}},{"t":"case","label":"Local Loan Co. v. Hunt","cite":"292 U.S. 234","y":1934,"id":"scdb/1933-054","sc":1,"sum":"1. A court of bankruptcy has jurisdiction by ancillary proceedings to enforce an order of discharge by enjoining the prosecution of suits brought against the debtor.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Mapother & Mapother, PSC v. Cooper (In re Downs)","cite":"103 F.3d 472","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/103/472/","by":{"0":"12"}},{"t":"case","label":"Marrama v. Citizens Bank (In re Marrama)","cite":"445 F.3d 518","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/445/518/","by":{"0":"7, 29, 30"}},{"t":"case","label":"Marrama v. DeGiancomo (In re Marrama)","cite":"316 B.R. 418","y":2004,"court":"B.A.P. 1st Cir.","url":"https://www.courtlistener.com/c/B.R./316/418/","by":{"0":"6, 29"}},{"t":"case","label":"Martin v. Cox","cite":"213 B.R. 571","y":1996,"court":"E.D. Ark.","url":"https://www.courtlistener.com/c/B.R./213/571/","by":{"0":"21"}},{"t":"case","label":"Martin v. Franklin Capital Corp.","cite":"126 S. Ct. 704","y":2005,"id":"2005/04-1140","sc":1,"sum":"The Court ruled that \"absent unusual circumstances, attorney's fees should not be awarded when the removing party has an objectively reasonable basis for removal.\" The Court admitted that Section 1447 is unclear on when attorney's fees should be added. The Court's reading of the statute detected no strong textual bias for or against awarding fees.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Molitor v. Edison (Molitor, In re)","cite":"76 F.3d 218","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/76/218/","op":1,"by":{"0":"17"}},{"t":"case","label":"Northwest Bank Worthington v. Ahlers","cite":"485 U.S. 197","y":1988,"id":"1987/86-958","sc":1,"op":1,"sum":"The absolute priority rule applies, and respondents' promise of future labor warrants no exception to its operation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Pearson v. First N.H. Mortgage Corp.","cite":"200 F.3d 30","y":1999,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/200/30/","by":{"0":"12"}},{"t":"case","label":"Roadway Express, Inc. v. Piper","cite":"447 U.S. 752","y":1980,"id":"1979/79-701","sc":1,"op":1,"sum":"Respondents were counsel for the plaintiffs in a civil rights class action in Federal District Court against petitioner alleging that its employment policies discriminated on the basis of race. Because respondents failed to comply with orders relating to discovery and the filing of briefs, petitioner moved to dismiss the suit and requested an award of attorney's fees and court costs under Federal Rule of Civil …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 10, 11"}},{"t":"case","label":"System Fed’n No. 91 v. Wright","cite":"364 U.S. 642","y":1961,"id":"1960/48","sc":1,"sum":"It erred in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"United States v. Hudson","cite":"11 U.S. 32","y":1812,"id":"scdb/1812-033","sc":1,"sum":"Absent.... Washi ngton, justice.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22, 26"}},{"t":"case","label":"Weinberger v. Romero-Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Case—Continued: Weiss v. First Citizens Bank & Trust Co. (In re Weiss)","cite":"111 F.3d 1159","y":1997,"url":"https://www.courtlistener.com/c/F.3d/111/1159/","by":{"0":"12"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","by":{"0":"7, 8, 11, 12, 13, 19, 7, 8, 11, 12, 13, 19"}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","subs":["(a)"],"stext":{"head":"§105. Power of court","paras":[[0,"(a) The court may issue any order, process, or judgment that is necessary or appropriate to carry out the provisions of this title. No provision of this title providing for the raising of an issue by a party in interest shall be construed to preclude the court from, sua sponte, taking any action or making any determination necessary or appropriate to enforce or implement court orders or rules, or to prevent an abuse of process."],[0,"(b) Notwithstanding subsection (a) of this section, a court may not appoint a receiver in a case under this title."],[0,"(c) The ability of any district judge or other officer or employee of a district court to exercise any of the authority or responsibilities conferred upon the court under this title shall be determined by reference to the provisions relating to such judge, officer, or employee set forth in title 28. This subsection shall not be interpreted to exclude bankruptcy judges and other officers or employees appointed pursuant to chapter 6 of title 28 from its operation."],[0,"(d) The court, on its own motion or on the request of a party in interest—"],[1,"(1) shall hold such status conferences as are necessary to further the expeditious and economical resolution of the case; and"],[1,"(2) unless inconsistent with another provision of this title or with applicable Federal Rules of Bankruptcy Procedure, may issue an order at any such conference prescribing such limitations and conditions as the court deems appropriate to ensure that the case is handled expeditiously and economically, including an order that—"],[2,"(A) sets the date by which the trustee must assume or reject an executory contract or unexpired lease; or"],[2,"(B) in a case under chapter 11 of this title—"],[3,"(i) sets a date by which the debtor, or trustee if one has been appointed, shall file a disclosure statement and plan;"],[3,"(ii) sets a date by which the debtor, or trustee if one has been appointed, shall solicit acceptances of a plan;"],[3,"(iii) sets the date by which a party in interest other than a debtor may file a plan;"],[3,"(iv) sets a date by which a proponent of a plan, other than the debtor, shall solicit acceptances of such plan;"],[3,"(v) fixes the scope and format of the notice to be provided regarding the hearing on approval of the disclosure statement; or"],[3,"(vi) provides that the hearing on approval of the disclosure statement may be combined with the hearing on confirmation of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/105?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§105. Power of court","tname":"Bankruptcy","by":{"0":"7, 8, 11, 12, 13, 19"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","by":{"0":"2, 2"}},{"t":"usc","label":"11 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/11/307","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 348","url":"https://www.law.cornell.edu/uscode/text/11/348","subs":["(e)"],"stext":{"head":"§348. Effect of conversion","paras":[[0,"(a) Conversion of a case from a case under one chapter of this title to a case under another chapter of this title constitutes an order for relief under the chapter to which the case is converted, but, except as provided in subsections (b) and (c) of this section, does not effect a change in the date of the filing of the petition, the commencement of the case, or the order for relief."],[0,"(b) Unless the court for cause orders otherwise, in sections 701(a), 727(a)(10), 727(b), 1102(a), 1110(a)(1), 1121(b), 1121(c), 1141(d)(4), 1201(a), 1221, 1228(a), 1301(a), and 1305(a) of this title, \"the order for relief under this chapter\" in a chapter to which a case has been converted under section 706, 1112, 1208, or 1307 of this title means the conversion of such case to such chapter."],[0,"(c) Sections 342 and 365(d) of this title apply in a case that has been converted under section 706, 1112, 1208, or 1307 of this title, as if the conversion order were the order for relief."],[0,"(d) A claim against the estate or the debtor that arises after the order for relief but before conversion in a case that is converted under section 1112, 1208, or 1307 of this title, other than a claim specified in section 503(b) of this title, shall be treated for all purposes as if such claim had arisen immediately before the date of the filing of the petition."],[0,"(e) Conversion of a case under section 706, 1112, 1208, or 1307 of this title terminates the service of any trustee or examiner that is serving in the case before such conversion."],[0,"(f)(1) Except as provided in paragraph (2), when a case under chapter 13 of this title is converted to a case under another chapter under this title—"],[1,"(A) property of the estate in the converted case shall consist of property of the estate, as of the date of filing of the petition, that remains in the possession of or is under the control of the debtor on the date of conversion;"],[1,"(B) valuations of property and of allowed secured claims in the chapter 13 case shall apply only in a case converted to a case under chapter 11 or 12, but not in a case converted to a case under chapter 7, with allowed secured claims in cases under chapters 11 and 12 reduced to the extent that they have been paid in accordance with the chapter 13 plan; and"],[1,"(C) with respect to cases converted from chapter 13—"],[2,"(i) the claim of any creditor holding security as of the date of the filing of the petition shall continue to be secured by that security unless the full amount of such claim determined under applicable nonbankruptcy law has been paid in full as of the date of conversion, notwithstanding any valuation or determination of the amount of an allowed secured claim made for the purposes of the case under chapter 13; and"],[2,"(ii) unless a prebankruptcy default has been fully cured under the plan at the time of conversion, in any proceeding under this title or otherwise, the default shall have the effect given under applicable nonbankruptcy law."],[0,"(2) If the debtor converts a case under chapter 13 of this title to a case under another chapter under this title in bad faith, the property of the estate in the converted case shall consist of the property of the estate as of the date of conversion."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/348?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§348. Effect of conversion","tname":"Bankruptcy","by":{"0":"22"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","by":{"0":"3"}},{"t":"usc","label":"11 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/11/507","by":{"0":"3"}},{"t":"usc","label":"11 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/11/521","subs":["(1)","(3)","(4)"],"stext":{"head":"§521. Debtor's duties","paras":[[0,"(a) The debtor shall—"],[1,"(1) file—"],[2,"(A) a list of creditors; and"],[2,"(B) unless the court orders otherwise—"],[3,"(i) a schedule of assets and liabilities;"],[3,"(ii) a schedule of current income and current expenditures;"],[3,"(iii) a statement of the debtor's financial affairs and, if section 342(b) applies, a certificate—"],[4,"(I) of an attorney whose name is indicated on the petition as the attorney for the debtor, or a bankruptcy petition preparer signing the petition under section 110(b)(1), indicating that such attorney or the bankruptcy petition preparer delivered to the debtor the notice required by section 342(b); or"],[4,"(II) if no attorney is so indicated, and no bankruptcy petition preparer signed the petition, of the debtor that such notice was received and read by the debtor;"],[3,"(iv) copies of all payment advices or other evidence of payment received within 60 days before the date of the filing of the petition, by the debtor from any employer of the debtor;"],[3,"(v) a statement of the amount of monthly net income, itemized to show how the amount is calculated; and"],[3,"(vi) a statement disclosing any reasonably anticipated increase in income or expenditures over the 12-month period following the date of the filing of the petition;"],[1,"(2) if an individual debtor's schedule of assets and liabilities includes debts which are secured by property of the estate—"],[2,"(A) within thirty days after the date of the filing of a petition under chapter 7 of this title or on or before the date of the meeting of creditors, whichever is earlier, or within such additional time as the court, for cause, within such period fixes, file with the clerk a statement of his intention with respect to the retention or surrender of such property and, if applicable, specifying that such property is claimed as exempt, that the debtor intends to redeem such property, or that the debtor intends to reaffirm debts secured by such property; and"],[2,"(B) within 30 days after the first date set for the meeting of creditors under section 341(a), or within such additional time as the court, for cause, within such 30-day period fixes, perform his intention with respect to such property, as specified by subparagraph (A) of this paragraph;"],[1,"except that nothing in subparagraphs (A) and (B) of this paragraph shall alter the debtor's or the trustee's rights with regard to such property under this title, except as provided in section 362(h);"],[1,"(3) if a trustee is serving in the case or an auditor is serving under section 586(f) of title 28, cooperate with the trustee as necessary to enable the trustee to perform the trustee's duties under this title;"],[1,"(4) if a trustee is serving in the case or an auditor is serving under section 586(f) of title 28, surrender to the trustee all property of the estate and any recorded information, including books, documents, records, and papers, relating to property of the estate, whether or not immunity is granted under section 344 of this title;"],[1,"(5) appear at the hearing required under section 524(d) of this title;"],[1,"(6) in a case under chapter 7 of this title in which the debtor is an individual, not retain possession of personal property as to which a creditor has an allowed claim for the purchase price secured in whole or in part by an interest in such personal property unless the debtor, not later than 45 days after the first meeting of creditors under section 341(a), either—"],[2,"(A) enters into an agreement with the creditor pursuant to section 524(c) with respect to the claim secured by such property; or"],[2,"(B) redeems such property from the security interest pursuant to section 722; and"],[1,"(7) unless a trustee is serving in the case, continue to perform the obligations required of the administrator (as defined in section 3 of the Employee Retirement Income Security Act of 1974) of an employee benefit plan if at the time of the commencement of the case the debtor (or any entity designated by the debtor) served as such administrator."],[0,"If the debtor fails to so act within the 45-day period referred to in paragraph (6), the stay under section 362(a) is terminated with respect to the personal property of the estate or of the debtor which is affected, such property shall no longer be property of the estate, and the creditor may take whatever action as to such property as is permitted by applicable nonbankruptcy law, unless the court determines on the motion of the trustee filed before the expiration of such 45-day period, and after notice and a hearing, that such property is of consequential value or benefit to the estate, orders appropriate adequate protection of the creditor's interest, and orders the debtor to deliver any collateral in the debtor's possession to the trustee."],[0,"(b) In addition to the requirements under subsection (a), a debtor who is an individual shall file with the court—"],[1,"(1) a certificate from the approved nonprofit budget and credit counseling agency that provided the debtor services under section 109(h) describing the services provided to the debtor; and"],[1,"(2) a copy of the debt repayment plan, if any, developed under section 109(h) through the approved nonprofit budget and credit counseling agency referred to in paragraph (1)."],[0,"(c) In addition to meeting the requirements under subsection (a), a debtor shall file with the court a record of any interest that a debtor has in an education individual retirement account (as defined in section 530(b)(1) of the Internal Revenue Code of 1986), an interest in an account in a qualified ABLE program (as defined in section 529A(b) of such Code,1 or under a qualified State tuition program (as defined in section 529(b)(1) of such Code)."],[0,"(d) If the debtor fails timely to take the action specified in subsection (a)(6) of this section, or in paragraphs (1) and (2) of section 362(h), with respect to property which a lessor or bailor owns and has leased, rented, or bailed to the debtor or as to which a creditor holds a security interest not otherwise voidable under section 522(f), 544, 545, 547, 548, or 549, nothing in this title shall prevent or limit the operation of a provision in the underlying lease or agreement that has the effect of placing the debtor in default under such lease or agreement by reason of the occurrence, pendency, or existence of a proceeding under this title or the insolvency of the debtor. Nothing in this subsection shall be deemed to justify limiting such a provision in any other circumstance."],[0,"(e)(1) If the debtor in a case under chapter 7 or 13 is an individual and if a creditor files with the court at any time a request to receive a copy of the petition, schedules, and statement of financial affairs filed by the debtor, then the court shall make such petition, such schedules, and such statement available to such creditor."],[0,"(2)(A) The debtor shall provide—"],[1,"(i) not later than 7 days before the date first set for the first meeting of creditors, to the trustee a copy of the Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such return) for the most recent tax year ending immediately before the commencement of the case and for which a Federal income tax return was filed; and"],[1,"(ii) at the same time the debtor complies with clause (i), a copy of such return (or if elected under clause (i), such transcript) to any creditor that timely requests such copy."],[0,"(B) If the debtor fails to comply with clause (i) or (ii) of subparagraph (A), the court shall dismiss the case unless the debtor demonstrates that the failure to so comply is due to circumstances beyond the control of the debtor."],[0,"(C) If a creditor requests a copy of such tax return or such transcript and if the debtor fails to provide a copy of such tax return or such transcript to such creditor at the time the debtor provides such tax return or such transcript to the trustee, then the court shall dismiss the case unless the debtor demonstrates that the failure to provide a copy of such tax return or such transcript is due to circumstances beyond the control of the debtor."],[0,"(3) If a creditor in a case under chapter 13 files with the court at any time a request to receive a copy of the plan filed by the debtor, then the court shall make available to such creditor a copy of the plan—"],[1,"(A) at a reasonable cost; and"],[1,"(B) not later than 7 days after such request is filed."],[0,"(f) At the request of the court, the United States trustee, or any party in interest in a case under chapter 7, 11, or 13, a debtor who is an individual shall file with the court—"],[1,"(1) at the same time filed with the taxing authority, a copy of each Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such tax return) with respect to each tax year of the debtor ending while the case is pending under such chapter;"],[1,"(2) at the same time filed with the taxing authority, each Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such tax return) that had not been filed with such authority as of the date of the commencement of the case and that was subsequently filed for any tax year of the debtor ending in the 3-year period ending on the date of the commencement of the case;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/521?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§521. Debtor's duties","tname":"Bankruptcy","by":{"0":"28, 3, 3, 3"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","by":{"0":"3"}},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(a)"],"stext":{"head":"§541. Property of the estate","paras":[[0,"(a) The commencement of a case under section 301, 302, or 303 of this title creates an estate. Such estate is comprised of all the following property, wherever located and by whomever held:"],[1,"(1) Except as provided in subsections (b) and (c)(2) of this section, all legal or equitable interests of the debtor in property as of the commencement of the case."],[1,"(2) All interests of the debtor and the debtor's spouse in community property as of the commencement of the case that is—"],[2,"(A) under the sole, equal, or joint management and control of the debtor; or"],[2,"(B) liable for an allowable claim against the debtor, or for both an allowable claim against the debtor and an allowable claim against the debtor's spouse, to the extent that such interest is so liable."],[1,"(3) Any interest in property that the trustee recovers under section 329(b), 363(n), 543, 550, 553, or 723 of this title."],[1,"(4) Any interest in property preserved for the benefit of or ordered transferred to the estate under section 510(c) or 551 of this title."],[1,"(5) Any interest in property that would have been property of the estate if such interest had been an interest of the debtor on the date of the filing of the petition, and that the debtor acquires or becomes entitled to acquire within 180 days after such date—"],[2,"(A) by bequest, devise, or inheritance;"],[2,"(B) as a result of a property settlement agreement with the debtor's spouse, or of an interlocutory or final divorce decree; or"],[2,"(C) as a beneficiary of a life insurance policy or of a death benefit plan."],[1,"(6) Proceeds, product, offspring, rents, or profits of or from property of the estate, except such as are earnings from services performed by an individual debtor after the commencement of the case."],[1,"(7) Any interest in property that the estate acquires after the commencement of the case."],[0,"(b) Property of the estate does not include—"],[1,"(1) any power that the debtor may exercise solely for the benefit of an entity other than the debtor;"],[1,"(2) any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease before the commencement of the case under this title, and ceases to include any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease during the case;"],[1,"(3) any eligibility of the debtor to participate in programs authorized under the Higher Education Act of 1965 (20 U.S.C. 1001 et seq.; 42 U.S.C. 2751 et seq.),1 or any accreditation status or State licensure of the debtor as an educational institution;"],[1,"(4) any interest of the debtor in liquid or gaseous hydrocarbons to the extent that—"],[2,"(A)(i) the debtor has transferred or has agreed to transfer such interest pursuant to a farmout agreement or any written agreement directly related to a farmout agreement; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 544(a)(3) of this title; or"],[2,"(B)(i) the debtor has transferred such interest pursuant to a written conveyance of a production payment to an entity that does not participate in the operation of the property from which such production payment is transferred; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 542 of this title;"],[1,"(5) funds placed in an education individual retirement account (as defined in section 530(b)(1) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(e) of the Internal Revenue Code of 1986); and"],[2,"(C) in the case of funds placed in all such accounts having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(6) funds used to purchase a tuition credit or certificate or contributed to an account in accordance with section 529(b)(1)(A) of the Internal Revenue Code of 1986 under a qualified State tuition program (as defined in section 529(b)(1) of such Code) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of the amounts paid or contributed to such tuition program was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were paid or contributed;"],[2,"(B) with respect to the aggregate amount paid or contributed to such program having the same designated beneficiary, only so much of such amount as does not exceed the total contributions permitted under section 529(b)(6) of such Code with respect to such beneficiary, as adjusted beginning on the date of the filing of the petition in a case under this title by the annual increase or decrease (rounded to the nearest tenth of 1 percent) in the education expenditure category of the Consumer Price Index prepared by the Department of Labor; and"],[2,"(C) in the case of funds paid or contributed to such program having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(7) any amount—"],[2,"(A) withheld by an employer from the wages of employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title; or"],[2,"(B) received by an employer from employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income, as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title;"],[1,"(8) subject to subchapter III of chapter 5, any interest of the debtor in property where the debtor pledged or sold tangible personal property (other than securities or written or printed evidences of indebtedness or title) as collateral for a loan or advance of money given by a person licensed under law to make such loans or advances, where—"],[2,"(A) the tangible personal property is in the possession of the pledgee or transferee;"],[2,"(B) the debtor has no obligation to repay the money, redeem the collateral, or buy back the property at a stipulated price; and"],[2,"(C) neither the debtor nor the trustee have exercised any right to redeem provided under the contract or State law, in a timely manner as provided under State law and section 108(b);"],[1,"(9) any interest in cash or cash equivalents that constitute proceeds of a sale by the debtor of a money order that is made—"],[2,"(A) on or after the date that is 14 days prior to the date on which the petition is filed; and"],[2,"(B) under an agreement with a money order issuer that prohibits the commingling of such proceeds with property of the debtor (notwithstanding that, contrary to the agreement, the proceeds may have been commingled with property of the debtor),"],[1,"unless the money order issuer had not taken action, prior to the filing of the petition, to require compliance with the prohibition; or"],[1,"(10) funds placed in an account of a qualified ABLE program (as defined in section 529A(b) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(h) of the Internal Revenue Code of 1986); and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/541?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§541. Property of the estate","tname":"Bankruptcy","by":{"0":"3"}},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","by":{"0":"5"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"0":"passim, 3"}},{"t":"usc","label":"11 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/11/704","subs":["(1)","(4)"],"stext":{"head":"§704. Duties of trustee","paras":[[0,"(a) The trustee shall—"],[1,"(1) collect and reduce to money the property of the estate for which such trustee serves, and close such estate as expeditiously as is compatible with the best interests of parties in interest;"],[1,"(2) be accountable for all property received;"],[1,"(3) ensure that the debtor shall perform his intention as specified in section 521(a)(2)(B) of this title;"],[1,"(4) investigate the financial affairs of the debtor;"],[1,"(5) if a purpose would be served, examine proofs of claims and object to the allowance of any claim that is improper;"],[1,"(6) if advisable, oppose the discharge of the debtor;"],[1,"(7) unless the court orders otherwise, furnish such information concerning the estate and the estate's administration as is requested by a party in interest;"],[1,"(8) if the business of the debtor is authorized to be operated, file with the court, with the United States trustee, and with any governmental unit charged with responsibility for collection or determination of any tax arising out of such operation, periodic reports and summaries of the operation of such business, including a statement of receipts and disbursements, and such other information as the United States trustee or the court requires;"],[1,"(9) make a final report and file a final account of the administration of the estate with the court and with the United States trustee;"],[1,"(10) if with respect to the debtor there is a claim for a domestic support obligation, provide the applicable notice specified in subsection (c);"],[1,"(11) if, at the time of the commencement of the case, the debtor (or any entity designated by the debtor) served as the administrator (as defined in section 3 of the Employee Retirement Income Security Act of 1974) of an employee benefit plan, continue to perform the obligations required of the administrator; and"],[1,"(12) use all reasonable and best efforts to transfer patients from a health care business that is in the process of being closed to an appropriate health care business that—"],[2,"(A) is in the vicinity of the health care business that is closing;"],[2,"(B) provides the patient with services that are substantially similar to those provided by the health care business that is in the process of being closed; and"],[2,"(C) maintains a reasonable quality of care."],[0,"(b)(1) With respect to a debtor who is an individual in a case under this chapter—"],[1,"(A) the United States trustee (or the bankruptcy administrator, if any) shall review all materials filed by the debtor and, not later than 10 days after the date of the first meeting of creditors, file with the court a statement as to whether the debtor's case would be presumed to be an abuse under section 707(b); and"],[1,"(B) not later than 7 days after receiving a statement under subparagraph (A), the court shall provide a copy of the statement to all creditors."],[0,"(2) The United States trustee (or bankruptcy administrator, if any) shall, not later than 30 days after the date of filing a statement under paragraph (1), either file a motion to dismiss or convert under section 707(b) or file a statement setting forth the reasons the United States trustee (or the bankruptcy administrator, if any) does not consider such a motion to be appropriate, if the United States trustee (or the bankruptcy administrator, if any) determines that the debtor's case should be presumed to be an abuse under section 707(b) and the product of the debtor's current monthly income, multiplied by 12 is not less than—"],[1,"(A) in the case of a debtor in a household of 1 person, the median family income of the applicable State for 1 earner; or"],[1,"(B) in the case of a debtor in a household of 2 or more individuals, the highest median family income of the applicable State for a family of the same number or fewer individuals."],[0,"(c)(1) In a case described in subsection (a)(10) to which subsection (a)(10) applies, the trustee shall—"],[1,"(A)(i) provide written notice to the holder of the claim described in subsection (a)(10) of such claim and of the right of such holder to use the services of the State child support enforcement agency established under sections 464 and 466 of the Social Security Act for the State in which such holder resides, for assistance in collecting child support during and after the case under this title;"],[1,"(ii) include in the notice provided under clause (i) the address and telephone number of such State child support enforcement agency; and"],[1,"(iii) include in the notice provided under clause (i) an explanation of the rights of such holder to payment of such claim under this chapter;"],[1,"(B)(i) provide written notice to such State child support enforcement agency of such claim; and"],[1,"(ii) include in the notice provided under clause (i) the name, address, and telephone number of such holder; and"],[1,"(C) at such time as the debtor is granted a discharge under section 727, provide written notice to such holder and to such State child support enforcement agency of—"],[2,"(i) the granting of the discharge;"],[2,"(ii) the last recent known address of the debtor;"],[2,"(iii) the last recent known name and address of the debtor's employer; and"],[2,"(iv) the name of each creditor that holds a claim that—"],[3,"(I) is not discharged under paragraph (2), (4), or (14A) of section 523(a); or"],[3,"(II) was reaffirmed by the debtor under section 524(c)."],[0,"(2)(A) The holder of a claim described in subsection (a)(10) or the State child support enforcement agency of the State in which such holder resides may request from a creditor described in paragraph (1)(C)(iv) the last known address of the debtor."],[0,"(B) Notwithstanding any other provision of law, a creditor that makes a disclosure of a last known address of a debtor in connection with a request made under subparagraph (A) shall not be liable by reason of making such disclosure."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/704?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§704. Duties of trustee","tname":"Bankruptcy","by":{"0":"3, 4"}},{"t":"usc","label":"11 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/11/706","subs":["(a)","(d)"],"stext":{"head":"§706. Conversion","paras":[[0,"(a) The debtor may convert a case under this chapter to a case under chapter 11, 12, or 13 of this title at any time, if the case has not been converted under section 1112, 1208, or 1307 of this title. Any waiver of the right to convert a case under this subsection is unenforceable."],[0,"(b) On request of a party in interest and after notice and a hearing, the court may convert a case under this chapter to a case under chapter 11 of this title at any time."],[0,"(c) The court may not convert a case under this chapter to a case under chapter 12 or 13 of this title unless the debtor requests or consents to such conversion."],[0,"(d) Notwithstanding any other provision of this section, a case may not be converted to a case under another chapter of this title unless the debtor may be a debtor under such chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/706?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":5,"head":"§706. Conversion","tname":"Bankruptcy","by":{"0":"passim, 14, 25"}},{"t":"usc","label":"11 U.S.C. § 707","url":"https://www.law.cornell.edu/uscode/text/11/707","subs":["(a)"],"stext":{"head":"§707. Dismissal of a case or conversion to a case under chapter 11 or 13","paras":[[0,"(a) The court may dismiss a case under this chapter only after notice and a hearing and only for cause, including—"],[1,"(1) unreasonable delay by the debtor that is prejudicial to creditors;"],[1,"(2) nonpayment of any fees or charges required under chapter 123 of title 28; and"],[1,"(3) failure of the debtor in a voluntary case to file, within fifteen days or such additional time as the court may allow after the filing of the petition commencing such case, the information required by paragraph (1) of section 521(a), but only on a motion by the United States trustee."],[0,"(b)(1) After notice and a hearing, the court, on its own motion or on a motion by the United States trustee, trustee (or bankruptcy administrator, if any), or any party in interest, may dismiss a case filed by an individual debtor under this chapter whose debts are primarily consumer debts, or, with the debtor's consent, convert such a case to a case under chapter 11 or 13 of this title, if it finds that the granting of relief would be an abuse of the provisions of this chapter. In making a determination whether to dismiss a case under this section, the court may not take into consideration whether a debtor has made, or continues to make, charitable contributions (that meet the definition of \"charitable contribution\" under section 548(d)(3)) to any qualified religious or charitable entity or organization (as that term is defined in section 548(d)(4))."],[0,"(2)(A)(i) In considering under paragraph (1) whether the granting of relief would be an abuse of the provisions of this chapter, the court shall presume abuse exists if the debtor's current monthly income reduced by the amounts determined under clauses (ii), (iii), and (iv), and multiplied by 60 is not less than the lesser of—"],[1,"(I) 25 percent of the debtor's nonpriority unsecured claims in the case, or $6,000,1 whichever is greater; or"],[1,"(II) $10,000.1"],[0,"(ii)(I) The debtor's monthly expenses shall be the debtor's applicable monthly expense amounts specified under the National Standards and Local Standards, and the debtor's actual monthly expenses for the categories specified as Other Necessary Expenses issued by the Internal Revenue Service for the area in which the debtor resides, as in effect on the date of the order for relief, for the debtor, the dependents of the debtor, and the spouse of the debtor in a joint case, if the spouse is not otherwise a dependent. Such expenses shall include reasonably necessary health insurance, disability insurance, and health savings account expenses for the debtor, the spouse of the debtor, or the dependents of the debtor. Notwithstanding any other provision of this clause, the monthly expenses of the debtor shall not include any payments for debts. In addition, the debtor's monthly expenses shall include the debtor's reasonably necessary expenses incurred to maintain the safety of the debtor and the family of the debtor from family violence as identified under section 302 of the Family Violence Prevention and Services Act, or other applicable Federal law. The expenses included in the debtor's monthly expenses described in the preceding sentence shall be kept confidential by the court. In addition, if it is demonstrated that it is reasonable and necessary, the debtor's monthly expenses may also include an additional allowance for food and clothing of up to 5 percent of the food and clothing categories as specified by the National Standards issued by the Internal Revenue Service."],[0,"(II) In addition, the debtor's monthly expenses may include, if applicable, the continuation of actual expenses paid by the debtor that are reasonable and necessary for care and support of an elderly, chronically ill, or disabled household member or member of the debtor's immediate family (including parents, grandparents, siblings, children, and grandchildren of the debtor, the dependents of the debtor, and the spouse of the debtor in a joint case who is not a dependent) and who is unable to pay for such reasonable and necessary expenses. Such monthly expenses may include, if applicable, contributions to an account of a qualified ABLE program to the extent such contributions are not excess contributions (as described in section 4973(h) of the Internal Revenue Code of 1986) and if the designated beneficiary of such account is a child, stepchild, grandchild, or stepgrandchild of the debtor."],[0,"(III) In addition, for a debtor eligible for chapter 13, the debtor's monthly expenses may include the actual administrative expenses of administering a chapter 13 plan for the district in which the debtor resides, up to an amount of 10 percent of the projected plan payments, as determined under schedules issued by the Executive Office for United States Trustees."],[0,"(IV) In addition, the debtor's monthly expenses may include the actual expenses for each dependent child less than 18 years of age, not to exceed $1,500 1 per year per child, to attend a private or public elementary or secondary school if the debtor provides documentation of such expenses and a detailed explanation of why such expenses are reasonable and necessary, and why such expenses are not already accounted for in the National Standards, Local Standards, or Other Necessary Expenses referred to in subclause (I)."],[0,"(V) In addition, the debtor's monthly expenses may include an allowance for housing and utilities, in excess of the allowance specified by the Local Standards for housing and utilities issued by the Internal Revenue Service, based on the actual expenses for home energy costs if the debtor provides documentation of such actual expenses and demonstrates that such actual expenses are reasonable and necessary."],[0,"(iii) The debtor's average monthly payments on account of secured debts shall be calculated as the sum of—"],[1,"(I) the total of all amounts scheduled as contractually due to secured creditors in each month of the 60 months following the date of the filing of the petition; and"],[1,"(II) any additional payments to secured creditors necessary for the debtor, in filing a plan under chapter 13 of this title, to maintain possession of the debtor's primary residence, motor vehicle, or other property necessary for the support of the debtor and the debtor's dependents, that serves as collateral for secured debts;"],[0,"divided by 60."],[0,"(iv) The debtor's expenses for payment of all priority claims (including priority child support and alimony claims) shall be calculated as the total amount of debts entitled to priority, divided by 60."],[0,"(B)(i) In any proceeding brought under this subsection, the presumption of abuse may only be rebutted by demonstrating special circumstances, such as a serious medical condition or a call or order to active duty in the Armed Forces, to the extent such special circumstances that justify additional expenses or adjustments of current monthly income for which there is no reasonable alternative."],[0,"(ii) In order to establish special circumstances, the debtor shall be required to itemize each additional expense or adjustment of income and to provide—"],[1,"(I) documentation for such expense or adjustment to income; and"],[1,"(II) a detailed explanation of the special circumstances that make such expenses or adjustment to income necessary and reasonable."],[0,"(iii) The debtor shall attest under oath to the accuracy of any information provided to demonstrate that additional expenses or adjustments to income are required."],[0,"(iv) The presumption of abuse may only be rebutted if the additional expenses or adjustments to income referred to in clause (i) cause the product of the debtor's current monthly income reduced by the amounts determined under clauses (ii), (iii), and (iv) of subparagraph (A) when multiplied by 60 to be less than the lesser of—"],[1,"(I) 25 percent of the debtor's nonpriority unsecured claims, or $6,000,1 whichever is greater; or"],[1,"(II) $10,000.1"],[0,"(C) As part of the schedule of current income and expenditures required under section 521, the debtor shall include a statement of the debtor's current monthly income, and the calculations that determine whether a presumption arises under subparagraph (A)(i), that show how each such amount is calculated."],[0,"(D) Subparagraphs (A) through (C) shall not apply, and the court may not dismiss or convert a case based on any form of means testing—"],[1,"(i) if the debtor is a disabled veteran (as defined in section 3741(1) of title 38), and the indebtedness occurred primarily during a period during which he or she was—"],[2,"(I) on active duty (as defined in section 101(d)(1) of title 10); or"],[2,"(II) performing a homeland defense activity (as defined in section 901(1) of title 32); or"],[1,"(ii) with respect to the debtor, while the debtor is—"],[2,"(I) on, and during the 540-day period beginning immediately after the debtor is released from, a period of active duty (as defined in section 101(d)(1) of title 10) of not less than 90 days; or"],[2,"(II) performing, and during the 540-day period beginning immediately after the debtor is no longer performing, a homeland defense activity (as defined in section 901(1) of title 32) performed for a period of not less than 90 days;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/707?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§707. Dismissal of a case or conversion to a case under chapter 11 or 13","tname":"Bankruptcy","by":{"0":"3, 28"}},{"t":"usc","label":"11 U.S.C. § 725","url":"https://www.law.cornell.edu/uscode/text/11/725","by":{"0":"27"}},{"t":"usc","label":"11 U.S.C. § 726","url":"https://www.law.cornell.edu/uscode/text/11/726","by":{"0":"3, 27, 30"}},{"t":"usc","label":"11 U.S.C. § 727","url":"https://www.law.cornell.edu/uscode/text/11/727","subs":["(a)","(a)(2)","(b)"],"stext":{"head":"§727. Discharge","paras":[[0,"(a) The court shall grant the debtor a discharge, unless—"],[1,"(1) the debtor is not an individual;"],[1,"(2) the debtor, with intent to hinder, delay, or defraud a creditor or an officer of the estate charged with custody of property under this title, has transferred, removed, destroyed, mutilated, or concealed, or has permitted to be transferred, removed, destroyed, mutilated, or concealed—"],[2,"(A) property of the debtor, within one year before the date of the filing of the petition; or"],[2,"(B) property of the estate, after the date of the filing of the petition;"],[1,"(3) the debtor has concealed, destroyed, mutilated, falsified, or failed to keep or preserve any recorded information, including books, documents, records, and papers, from which the debtor's financial condition or business transactions might be ascertained, unless such act or failure to act was justified under all of the circumstances of the case;"],[1,"(4) the debtor knowingly and fraudulently, in or in connection with the case—"],[2,"(A) made a false oath or account;"],[2,"(B) presented or used a false claim;"],[2,"(C) gave, offered, received, or attempted to obtain money, property, or advantage, or a promise of money, property, or advantage, for acting or forbearing to act; or"],[2,"(D) withheld from an officer of the estate entitled to possession under this title, any recorded information, including books, documents, records, and papers, relating to the debtor's property or financial affairs;"],[1,"(5) the debtor has failed to explain satisfactorily, before determination of denial of discharge under this paragraph, any loss of assets or deficiency of assets to meet the debtor's liabilities;"],[1,"(6) the debtor has refused, in the case—"],[2,"(A) to obey any lawful order of the court, other than an order to respond to a material question or to testify;"],[2,"(B) on the ground of privilege against self-incrimination, to respond to a material question approved by the court or to testify, after the debtor has been granted immunity with respect to the matter concerning which such privilege was invoked; or"],[2,"(C) on a ground other than the properly invoked privilege against self-incrimination, to respond to a material question approved by the court or to testify;"],[1,"(7) the debtor has committed any act specified in paragraph (2), (3), (4), (5), or (6) of this subsection, on or within one year before the date of the filing of the petition, or during the case, in connection with another case, under this title or under the Bankruptcy Act, concerning an insider;"],[1,"(8) the debtor has been granted a discharge under this section, under section 1141 of this title, or under section 14, 371, or 476 of the Bankruptcy Act, in a case commenced within 8 years before the date of the filing of the petition;"],[1,"(9) the debtor has been granted a discharge under section 1228 or 1328 of this title, or under section 660 or 661 of the Bankruptcy Act, in a case commenced within six years before the date of the filing of the petition, unless payments under the plan in such case totaled at least—"],[2,"(A) 100 percent of the allowed unsecured claims in such case; or"],[2,"(B)(i) 70 percent of such claims; and"],[2,"(ii) the plan was proposed by the debtor in good faith, and was the debtor's best effort;"],[1,"(10) the court approves a written waiver of discharge executed by the debtor after the order for relief under this chapter;"],[1,"(11) after filing the petition, the debtor failed to complete an instructional course concerning personal financial management described in section 111, except that this paragraph shall not apply with respect to a debtor who is a person described in section 109(h)(4) or who resides in a district for which the United States trustee (or the bankruptcy administrator, if any) determines that the approved instructional courses are not adequate to service the additional individuals who would otherwise be required to complete such instructional courses under this section (The United States trustee (or the bankruptcy administrator, if any) who makes a determination described in this paragraph shall review such determination not later than 1 year after the date of such determination, and not less frequently than annually thereafter.); or"],[1,"(12) the court after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge finds that there is reasonable cause to believe that—"],[2,"(A) section 522(q)(1) may be applicable to the debtor; and"],[2,"(B) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B)."],[0,"(b) Except as provided in section 523 of this title, a discharge under subsection (a) of this section discharges the debtor from all debts that arose before the date of the order for relief under this chapter, and any liability on a claim that is determined under section 502 of this title as if such claim had arisen before the commencement of the case, whether or not a proof of claim based on any such debt or liability is filed under section 501 of this title, and whether or not a claim based on any such debt or liability is allowed under section 502 of this title."],[0,"(c)(1) The trustee, a creditor, or the United States trustee may object to the granting of a discharge under subsection (a) of this section."],[0,"(2) On request of a party in interest, the court may order the trustee to examine the acts and conduct of the debtor to determine whether a ground exists for denial of discharge."],[0,"(d) On request of the trustee, a creditor, or the United States trustee, and after notice and a hearing, the court shall revoke a discharge granted under subsection (a) of this section if—"],[1,"(1) such discharge was obtained through the fraud of the debtor, and the requesting party did not know of such fraud until after the granting of such discharge;"],[1,"(2) the debtor acquired property that is property of the estate, or became entitled to acquire property that would be property of the estate, and knowingly and fraudulently failed to report the acquisition of or entitlement to such property, or to deliver or surrender such property to the trustee;"],[1,"(3) the debtor committed an act specified in subsection (a)(6) of this section; or"],[1,"(4) the debtor has failed to explain satisfactorily—"],[2,"(A) a material misstatement in an audit referred to in section 586(f) of title 28; or"],[2,"(B) a failure to make available for inspection all necessary accounts, papers, documents, financial records, files, and all other papers, things, or property belonging to the debtor that are requested for an audit referred to in section 586(f) of title 28."],[0,"(e) The trustee, a creditor, or the United States trustee may request a revocation of a discharge—"],[1,"(1) under subsection (d)(1) of this section within one year after such discharge is granted; or"],[1,"(2) under subsection (d)(2) or (d)(3) of this section before the later of—"],[2,"(A) one year after the granting of such discharge; and"],[2,"(B) the date the case is closed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/727?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§727. Discharge","tname":"Bankruptcy","by":{"0":"27, 30, 3, 27, 7, 3, 3"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 1112","url":"https://www.law.cornell.edu/uscode/text/11/1112","subs":["(a)","(b)"],"stext":{"head":"§1112. Conversion or dismissal","paras":[[0,"(a) The debtor may convert a case under this chapter to a case under chapter 7 of this title unless—"],[1,"(1) the debtor is not a debtor in possession;"],[1,"(2) the case originally was commenced as an involuntary case under this chapter; or"],[1,"(3) the case was converted to a case under this chapter other than on the debtor's request."],[0,"(b)(1) Except as provided in paragraph (2) and subsection (c), on request of a party in interest, and after notice and a hearing, the court shall convert a case under this chapter to a case under chapter 7 or dismiss a case under this chapter, whichever is in the best interests of creditors and the estate, for cause unless the court determines that the appointment under section 1104(a) of a trustee or an examiner is in the best interests of creditors and the estate."],[0,"(2) The court may not convert a case under this chapter to a case under chapter 7 or dismiss a case under this chapter if the court finds and specifically identifies unusual circumstances establishing that converting or dismissing the case is not in the best interests of creditors and the estate, and the debtor or any other party in interest establishes that—"],[1,"(A) there is a reasonable likelihood that a plan will be confirmed within the timeframes established in sections 1121(e) and 1129(e) of this title, or if such sections do not apply, within a reasonable period of time; and"],[1,"(B) the grounds for converting or dismissing the case include an act or omission of the debtor other than under paragraph (4)(A)—"],[2,"(i) for which there exists a reasonable justification for the act or omission; and"],[2,"(ii) that will be cured within a reasonable period of time fixed by the court."],[0,"(3) The court shall commence the hearing on a motion under this subsection not later than 30 days after filing of the motion, and shall decide the motion not later than 15 days after commencement of such hearing, unless the movant expressly consents to a continuance for a specific period of time or compelling circumstances prevent the court from meeting the time limits established by this paragraph."],[0,"(4) For purposes of this subsection, the term \"cause\" includes—"],[1,"(A) substantial or continuing loss to or diminution of the estate and the absence of a reasonable likelihood of rehabilitation;"],[1,"(B) gross mismanagement of the estate;"],[1,"(C) failure to maintain appropriate insurance that poses a risk to the estate or to the public;"],[1,"(D) unauthorized use of cash collateral substantially harmful to 1 or more creditors;"],[1,"(E) failure to comply with an order of the court;"],[1,"(F) unexcused failure to satisfy timely any filing or reporting requirement established by this title or by any rule applicable to a case under this chapter;"],[1,"(G) failure to attend the meeting of creditors convened under section 341(a) or an examination ordered under rule 2004 of the Federal Rules of Bankruptcy Procedure without good cause shown by the debtor;"],[1,"(H) failure timely to provide information or attend meetings reasonably requested by the United States trustee (or the bankruptcy administrator, if any);"],[1,"(I) failure timely to pay taxes owed after the date of the order for relief or to file tax returns due after the date of the order for relief;"],[1,"(J) failure to file a disclosure statement, or to file or confirm a plan, within the time fixed by this title or by order of the court;"],[1,"(K) failure to pay any fees or charges required under chapter 123 of title 28;"],[1,"(L) revocation of an order of confirmation under section 1144;"],[1,"(M) inability to effectuate substantial consummation of a confirmed plan;"],[1,"(N) material default by the debtor with respect to a confirmed plan;"],[1,"(O) termination of a confirmed plan by reason of the occurrence of a condition specified in the plan; and"],[1,"(P) failure of the debtor to pay any domestic support obligation that first becomes payable after the date of the filing of the petition."],[0,"(c) The court may not convert a case under this chapter to a case under chapter 7 of this title if the debtor is a farmer or a corporation that is not a moneyed, business, or commercial corporation, unless the debtor requests such conversion."],[0,"(d) The court may convert a case under this chapter to a case under chapter 12 or 13 of this title only if—"],[1,"(1) the debtor requests such conversion;"],[1,"(2) the debtor has not been discharged under section 1141(d) of this title; and"],[1,"(3) if the debtor requests conversion to chapter 12 of this title, such conversion is equitable."],[0,"(e) Except as provided in subsections (c) and (f), the court, on request of the United States trustee, may convert a case under this chapter to a case under chapter 7 of this title or may dismiss a case under this chapter, whichever is in the best interest of creditors and the estate if the debtor in a voluntary case fails to file, within fifteen days after the filing of the petition commencing such case or such additional time as the court may allow, the information required by paragraph (1) of section 521(a), including a list containing the names and addresses of the holders of the twenty largest unsecured claims (or of all unsecured claims if there are fewer than twenty unsecured claims), and the approximate dollar amounts of each of such claims."],[0,"(f) Notwithstanding any other provision of this section, a case may not be converted to a case under another chapter of this title unless the debtor may be a debtor under such chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1112?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1112. Conversion or dismissal","tname":"Bankruptcy","by":{"0":"4, 4, 28"}},{"t":"usc","label":"11 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/11/1201","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 1208","url":"https://www.law.cornell.edu/uscode/text/11/1208","subs":["(a)","(c)"],"by":{"0":"4, 28"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"0":"passim, 3"}},{"t":"usc","label":"11 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/11/1304","by":{"0":"3"}},{"t":"usc","label":"11 U.S.C. § 1306","url":"https://www.law.cornell.edu/uscode/text/11/1306","subs":["(b)"],"by":{"0":"3, 22"}},{"t":"usc","label":"11 U.S.C. § 1307","url":"https://www.law.cornell.edu/uscode/text/11/1307","subs":["(a)","(c)"],"stext":{"head":"§1307. Conversion or dismissal","paras":[[0,"(a) The debtor may convert a case under this chapter to a case under chapter 7 of this title at any time. Any waiver of the right to convert under this subsection is unenforceable."],[0,"(b) On request of the debtor at any time, if the case has not been converted under section 706, 1112, or 1208 of this title, the court shall dismiss a case under this chapter. Any waiver of the right to dismiss under this subsection is unenforceable."],[0,"(c) Except as provided in subsection (f) of this section, on request of a party in interest or the United States trustee and after notice and a hearing, the court may convert a case under this chapter to a case under chapter 7 of this title, or may dismiss a case under this chapter, whichever is in the best interests of creditors and the estate, for cause, including—"],[1,"(1) unreasonable delay by the debtor that is prejudicial to creditors;"],[1,"(2) nonpayment of any fees and charges required under chapter 123 of title 28;"],[1,"(3) failure to file a plan timely under section 1321 of this title;"],[1,"(4) failure to commence making timely payments under section 1326 of this title;"],[1,"(5) denial of confirmation of a plan under section 1325 of this title and denial of a request made for additional time for filing another plan or a modification of a plan;"],[1,"(6) material default by the debtor with respect to a term of a confirmed plan;"],[1,"(7) revocation of the order of confirmation under section 1330 of this title, and denial of confirmation of a modified plan under section 1329 of this title;"],[1,"(8) termination of a confirmed plan by reason of the occurrence of a condition specified in the plan other than completion of payments under the plan;"],[1,"(9) only on request of the United States trustee, failure of the debtor to file, within fifteen days, or such additional time as the court may allow, after the filing of the petition commencing such case, the information required by paragraph (1) of section 521(a);"],[1,"(10) only on request of the United States trustee, failure to timely file the information required by paragraph (2) of section 521(a); or"],[1,"(11) failure of the debtor to pay any domestic support obligation that first becomes payable after the date of the filing of the petition."],[0,"(d) Except as provided in subsection (f) of this section, at any time before the confirmation of a plan under section 1325 of this title, on request of a party in interest or the United States trustee and after notice and a hearing, the court may convert a case under this chapter to a case under chapter 11 or 12 of this title."],[0,"(e) Upon the failure of the debtor to file a tax return under section 1308, on request of a party in interest or the United States trustee and after notice and a hearing, the court shall dismiss a case or convert a case under this chapter to a case under chapter 7 of this title, whichever is in the best interest of the creditors and the estate."],[0,"(f) The court may not convert a case under this chapter to a case under chapter 7, 11, or 12 of this title if the debtor is a farmer, unless the debtor requests such conversion."],[0,"(g) Notwithstanding any other provision of this section, a case may not be converted to a case under another chapter of this title unless the debtor may be a debtor under such chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1307?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§1307. Conversion or dismissal","tname":"Bankruptcy","by":{"0":"4, passim"}},{"t":"usc","label":"11 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/11/1321","stext":{"head":"§1321. Filing of plan","paras":[[0,"The debtor shall file a plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1321?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1321. Filing of plan","tname":"Bankruptcy","by":{"0":"3"}},{"t":"usc","label":"11 U.S.C. § 1322","url":"https://www.law.cornell.edu/uscode/text/11/1322","by":{"0":"19"}},{"t":"usc","label":"11 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/11/1325","subs":["(a)(4)","(a)(7)"],"stext":{"head":"§1325. Confirmation of plan","paras":[[0,"(a) Except as provided in subsection (b), the court shall confirm a plan if—"],[1,"(1) The plan complies with the provisions of this chapter and with the other applicable provisions of this title;"],[1,"(2) any fee, charge, or amount required under chapter 123 of title 28, or by the plan, to be paid before confirmation, has been paid;"],[1,"(3) the plan has been proposed in good faith and not by any means forbidden by law;"],[1,"(4) the value, as of the effective date of the plan, of property to be distributed under the plan on account of each allowed unsecured claim is not less than the amount that would be paid on such claim if the estate of the debtor were liquidated under chapter 7 of this title on such date;"],[1,"(5) with respect to each allowed secured claim provided for by the plan—"],[2,"(A) the holder of such claim has accepted the plan;"],[2,"(B)(i) the plan provides that—"],[3,"(I) the holder of such claim retain the lien securing such claim until the earlier of—"],[4,"(aa) the payment of the underlying debt determined under nonbankruptcy law; or"],[4,"(bb) discharge under section 1328; and"],[3,"(II) if the case under this chapter is dismissed or converted without completion of the plan, such lien shall also be retained by such holder to the extent recognized by applicable nonbankruptcy law;"],[2,"(ii) the value, as of the effective date of the plan, of property to be distributed under the plan on account of such claim is not less than the allowed amount of such claim; and"],[2,"(iii) if—"],[3,"(I) property to be distributed pursuant to this subsection is in the form of periodic payments, such payments shall be in equal monthly amounts; and"],[3,"(II) the holder of the claim is secured by personal property, the amount of such payments shall not be less than an amount sufficient to provide to the holder of such claim adequate protection during the period of the plan; or"],[2,"(C) the debtor surrenders the property securing such claim to such holder;"],[1,"(6) the debtor will be able to make all payments under the plan and to comply with the plan;"],[1,"(7) the action of the debtor in filing the petition was in good faith;"],[1,"(8) the debtor has paid all amounts that are required to be paid under a domestic support obligation and that first become payable after the date of the filing of the petition if the debtor is required by a judicial or administrative order, or by statute, to pay such domestic support obligation; and"],[1,"(9) the debtor has filed all applicable Federal, State, and local tax returns as required by section 1308."],[0,"For purposes of paragraph (5), section 506 shall not apply to a claim described in that paragraph if the creditor has a purchase money security interest securing the debt that is the subject of the claim, the debt was incurred within the 910-day period preceding the date of the filing of the petition, and the collateral for that debt consists of a motor vehicle (as defined in section 30102 of title 49) acquired for the personal use of the debtor, or if collateral for that debt consists of any other thing of value, if the debt was incurred during the 1-year period preceding that filing."],[0,"(b)(1) If the trustee or the holder of an allowed unsecured claim objects to the confirmation of the plan, then the court may not approve the plan unless, as of the effective date of the plan—"],[1,"(A) the value of the property to be distributed under the plan on account of such claim is not less than the amount of such claim; or"],[1,"(B) the plan provides that all of the debtor's projected disposable income to be received in the applicable commitment period beginning on the date that the first payment is due under the plan will be applied to make payments to unsecured creditors under the plan."],[0,"(2) For purposes of this subsection, the term \"disposable income\" means current monthly income received by the debtor (other than child support payments, foster care payments, or disability payments for a dependent child made in accordance with applicable nonbankruptcy law to the extent reasonably necessary to be expended for such child) less amounts reasonably necessary to be expended—"],[1,"(A)(i) for the maintenance or support of the debtor or a dependent of the debtor, or for a domestic support obligation, that first becomes payable after the date the petition is filed; and"],[1,"(ii) for charitable contributions (that meet the definition of \"charitable contribution\" under section 548(d)(3)) to a qualified religious or charitable entity or organization (as defined in section 548(d)(4)) in an amount not to exceed 15 percent of gross income of the debtor for the year in which the contributions are made; and"],[1,"(B) if the debtor is engaged in business, for the payment of expenditures necessary for the continuation, preservation, and operation of such business."],[0,"(3) Amounts reasonably necessary to be expended under paragraph (2), other than subparagraph (A)(ii) of paragraph (2), shall be determined in accordance with subparagraphs (A) and (B) of section 707(b)(2), if the debtor has current monthly income, when multiplied by 12, greater than—"],[1,"(A) in the case of a debtor in a household of 1 person, the median family income of the applicable State for 1 earner;"],[1,"(B) in the case of a debtor in a household of 2, 3, or 4 individuals, the highest median family income of the applicable State for a family of the same number or fewer individuals; or"],[1,"(C) in the case of a debtor in a household exceeding 4 individuals, the highest median family income of the applicable State for a family of 4 or fewer individuals, plus $525 1 per month for each individual in excess of 4."],[0,"(4) For purposes of this subsection, the \"applicable commitment period\"—"],[1,"(A) subject to subparagraph (B), shall be—"],[2,"(i) 3 years; or"],[2,"(ii) not less than 5 years, if the current monthly income of the debtor and the debtor's spouse combined, when multiplied by 12, is not less than—"],[3,"(I) in the case of a debtor in a household of 1 person, the median family income of the applicable State for 1 earner;"],[3,"(II) in the case of a debtor in a household of 2, 3, or 4 individuals, the highest median family income of the applicable State for a family of the same number or fewer individuals; or"],[3,"(III) in the case of a debtor in a household exceeding 4 individuals, the highest median family income of the applicable State for a family of 4 or fewer individuals, plus $525 1 per month for each individual in excess of 4; and"],[1,"(B) may be less than 3 or 5 years, whichever is applicable under subparagraph (A), but only if the plan provides for payment in full of all allowed unsecured claims over a shorter period."],[0,"(c) After confirmation of a plan, the court may order any entity from whom the debtor receives income to pay all or any part of such income to the trustee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1325?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1325. Confirmation of plan","tname":"Bankruptcy","by":{"0":"19, 22, 22"}},{"t":"usc","label":"11 U.S.C. § 1328","url":"https://www.law.cornell.edu/uscode/text/11/1328","subs":["(b)(2)"],"by":{"0":"19"}},{"t":"usc","label":"28 U.S.C. § 581","url":"https://www.law.cornell.edu/uscode/text/28/581","subs":["(a)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1746","url":"https://www.law.cornell.edu/uscode/text/28/1746","stext":{"head":"§1746. Unsworn declarations under penalty of perjury","paras":[[0,"Wherever, under any law of the United States or under any rule, regulation, order, or requirement made pursuant to law, any matter is required or permitted to be supported, evidenced, established, or proved by the sworn declaration, verification, certificate, statement, oath, or affidavit, in writing of the person making the same (other than a deposition, or an oath of office, or an oath required to be taken before a specified official other than a notary public), such matter may, with like force and effect, be supported, evidenced, established, or proved by the unsworn declaration, certificate, verification, or statement, in writing of such person which is subscribed by him, as true under penalty of perjury, and dated, in substantially the following form:"],[0,"(1) If executed without the United States: \"I declare (or certify, verify, or state) under penalty of perjury under the laws of the United States of America that the foregoing is true and correct. Executed on (date)."],[0,"(Signature)\"."],[0,"(2) If executed within the United States, its territories, possessions, or commonwealths: \"I declare (or certify, verify, or state) under penalty of perjury that the foregoing is true and correct. Executed on (date)."],[0,"(Signature)\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1746?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1746. Unsworn declarations under penalty of perjury","tname":"Judiciary and Judicial Procedure","by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1927","url":"https://www.law.cornell.edu/uscode/text/28/1927","by":{"0":"18"}},{"t":"law","label":"Pub. L. No. 109-8","url":"https://www.govinfo.gov/link/plaw/109/public/8","by":{"0":"22"}}]};